"""Curated starter plant data for temperate Central/Eastern Europe (Romania-focused).

IMPORTANT - how to read this data
  * It is a hand-curated STARTER SET written from general horticultural and botanical knowledge. It is not a
    citation-backed database and is not exhaustive. Entries are meant to be reviewed and extended by the user.
  * `native`: 'native' = occurs naturally in Romania; 'naturalised' = long established; 'introduced' = cultivated.
  * Months are 1-12 and approximate for a continental temperate climate (hardiness zone 6-7); they shift with
    altitude and year. `zone` is the minimum USDA hardiness zone.
  * `med` is TRADITIONAL use only, not evidence of efficacy. `tox` is a safety warning. Nothing here is medical advice.
"""

PLANTS: list[dict] = []

# Woody plants that keep their leaves through winter (used by the shadow model: evergreens shade in winter too).
EVERGREEN = {"spruce", "fir", "scotspine", "yew"}


def P(id, name, sci, family, cat, native, edible, sun, water, h, spacing, fl=None, hv=None, sow=None, *, ro=None,
      soil="", zone=None, canopy=None, prop="", wild="", root="medium", shade_tol=False, notes="", med=None, tox=None,
      poll=None, place=None, also=()):
    cats = [cat, *also]
    if med:
        cats.append("medicinal")
    if edible == "toxic":  # only genuinely toxic plants are listed in the Toxic category; other warnings show as "caution"
        cats.append("toxic")
    if native == "native":
        cats.append("native")
    if place is None:
        place = "tree" if cat in ("fruit_tree", "nut_tree", "ornamental_tree", "forest_tree") else "bush" if cat in ("shrub", "fruit_shrub") else "plant"
    PLANTS.append(dict(id=id, name=name, ro=ro, sci=sci, family=family, cats=cats, native=native, edible=edible, sun=sun,
                       water=water, height=h, spacing=spacing, flower=fl, harvest=hv, sow=sow, soil=soil, zone=zone,
                       canopy=canopy, prop=prop, wildlife=wild, root=root, shadeTol=shade_tol, notes=notes, med=med,
                       tox=tox, pollination=poll, place=place, leaf="evergreen" if id in EVERGREEN else "deciduous"))


